"""Three authored journeys. Method rules are data, never runtime language-model decisions."""
from beacon_expedition import method, specialist, team, magic

CAST=['mira','tamsin','iona','aurelia','neris','sabine','koharu','zahra','fenna','kaede','elowen','nyssara','sylva']

def obstacle(key,name,text,patient,expert,attribute,skill,partners,form,spelltext,ritual,principles,lasting):
 return {'id':key,'name':name,'description':text,'choices':{
  'patient':method(patient,3,'Three phases, no supplies or attribute requirement. Safe alone.'),
  'specialist':specialist(expert,attribute,skill,'One phase. A qualified member of the actual party leads.'),
  'team':team(partners[0],partners[1],partners[2],'One phase. Two distinct, qualified party members fill the listed roles.'),
  'spell:'+form:magic(spelltext,form,'One phase; this specific obstacle is resolved. Pay the prepared spell’s components once.'),
  'ritual':method(ritual,2,'Two phases. Inscribe a permanent change at this site: '+lasting+' Requires a present conductor who has learned both listed principles; 1 moon glass and 1 binding thread, paid once.',ritualPrinciples=principles,inputs={'moon-glass':1,'binding-thread':1},lasting=lasting)}}

