for key,d in SITES.items():
 d['id']=key
 d['definition']={'id':key,'name':d['name'],'description':d['description'],'approaches':{'survey':{'name':'Follow the whole journey','description':'One phase out, six obstacles and a final decision, then one phase home. Ordinary routes are free and safe alone. Each obstacle also has specialist, teamwork, prepared spell and permanent ritual routes.','reward':'3 advancement for each returning participant, 2 moon glass, 3 binding thread, shared practical knowledge, and '+d['legacy']+'. Rewards arrive once, on a completed return.'}}}
 d['steps'].append({'id':'future','name':d['decision'],'description':'Every recovered object is preserved. Choose the commitment recorded in the final report; no option discards another find.','choices':{k:method(v[0],1,v[1]) for k,v in d['endings'].items()}})

# Each companion has a distinct line at each destination, and a personal camp exchange.
VOICES={
 'mira':('A flood mark is a measurement and a memory. I want both in the atlas.','Please keep the uncertain readings. A tidy error is still an error.','The servants kept two books because the guests only wanted to read one.'),
 'tamsin':('We should find out who kept clearing these drains after everyone else stopped noticing.','Who carried the spare cable up here? The log ought to say.','A beautiful invitation can hide a very long list of unpaid work.'),
 'iona':('That bell has a lovely note. I would like it to mean something hopeful again.','The speaking tube sings when the wind changes. I am resisting the obvious duet.','Eight bars forever sounds romantic only to someone who has never rehearsed.'),
 'aurelia':('A warning is useful when people know they can trust it.','We need a safe way back before we celebrate a daring way forward.','An invitation should never become a command.'),
 'neris':('The bypass is less elegant than the main drain. I suspect it is also why the building survived.','This interlock is a good idea badly explained. I recognise the temptation.','The door was given impeccable manners and terrible instructions.'),
 
 'sabine':('Wet cloaks have their charms in paintings. In practice I vote for the changing screen.','I can look windswept after we are safely inside. It need not be a full-time commitment.','At last, a ruin that understands accessories. I am still suspicious of its hospitality.'),
 'koharu':('I would like to take home a working model, not a heroic story about a pump.','The worn part tells us more than the polished plaque.','The music roll is repairable. Whether anyone wants to dance is a separate question.'),
 'zahra':('We can move the stone. First we find out what else it is holding up.','Tie the rope properly. I refuse to become an inspiring cautionary tale.','If the door wants a title, tell it I am Acting Director of Getting Through Doors.'),
 'fenna':('The high-water route is still here. Whoever marked it expected someone ordinary to need it.','The long way around has excellent views and very few opportunities to fall.','The servant passage goes everywhere the grand staircase pretends to go.'),
 'kaede':('Listen between the bell strokes. There is a quieter pattern underneath.','Balance is partly knowing when to stop moving.','The dancers cannot choose another step. We can.'),
 'elowen':('A memorial needs space for living people to sit beside it.','There is moss on the sheltered side. It has already done half our route finding.','The winter garden kept growing after the invitations stopped.'),
 'nyssara':('A dead keeper is still owed a finished watch.','A warning light should not require someone to stay alone forever.','The echo is not a person we can persuade into owing us affection.'),
 'sylva':('The water has made a home here. We can guide it without pretending it was an intruder.','I like the places where the bridge bends a little and keeps standing.','A garden growing through a ballroom is an interesting criticism of the ballroom.')
}
CAMPS={
 'mira':('A margin for something personal','Mira shuts her notebook and deliberately sets it beyond reach. “Ask me something I cannot answer with a diagram.”','“An hour reading something I did not choose for research,” Mira says. “Then a walk with someone willing to argue about the ending. I want to collect the stories people actually reread, even the ones they hide behind respectable books.” She asks which would go on your shelf.'),
 'tamsin':('A chair she does not have to earn','Tamsin has claimed the comfortable seat. “I have finished being useful for the next few minutes. You may join me on those terms.”','“A customer asked me to rebind his accounts so they would look less alarming,” Tamsin says. “I suggested smaller numbers. He asked whether I could do that too.” She accepts a cup from you. “I repaired the cover. The debts remained impressively intact.”'),
 'iona':('An audience of one','Iona offers you a tiny, exaggerated bow. “One quiet song. Afterwards you may applaud with your eyebrows.”','Iona sings softly, “Bring the boat home, leave your boots by the door.” On the repeated line she points at your muddy boots. You applaud with exaggerated eyebrows. “An exacting audience,” she says, pleased.'),
 'aurelia':('The watch can wait','Aurelia loosens her travelling collar and sits where she can stop watching the door. “I trust the shelter. I am practising behaving as though I do.”','Aurelia points out a seam in her travelling gloves. “I have mended that three times. I keep them because a new pair never fits between the fingers.” She turns the worn leather over. “Tomorrow I shall ask about a lining. Tonight I would like your opinion on the tea.”'),
 'neris':('An experiment in doing nothing','Neris admits she has invented three repairs since sitting down. “Please distract me before I create a fourth.”','You propose using the buckle as a crown for a very small monarch. Neris turns it sideways. “A portrait frame for a beetle.” Then she considers a folding handle and catches herself. “No. Back to the beetle. Does it look sufficiently royal?”'),
 
 'sabine':('The unnecessary flourish','Sabine adjusts a ribbon with theatrical care. “There. An entirely unnecessary improvement to expedition morale.”','You admire the flourish. She admits she likes looking lovely for her own amusement, then asks which part amused you.'),
 'koharu':('Hands without a task','Koharu holds her cup in both hands. “If I put this down, I shall find something to mend. Help me maintain the obstacle.”','“I want to carve something that serves no purpose,” Koharu says. “A bird so offended that nobody can mistake it for a hook.” You ask how she will keep people from hanging coats on it. “Carve two. Let them look disapprovingly at each other.”'),
 'zahra':('A very dignified blanket','Zahra has wrapped herself in a blanket with only her face showing. “You may address the expedition commander. Briefly.”','“Two biscuits remain, Commander,” you report. “Both requesting immediate transfer.” Zahra extends one hand from the blanket. “Granted. Send the first to me and retain the second as your reward for accurate intelligence.” She breaks character when you salute with it.'),
 'fenna':('The route she chose to stay on','Fenna stretches her legs and watches the doorway. “Usually I would be wondering what is round the next corner. This is a pleasant exception.”','“You asked about the innkeeper before asking whether the shortcut saved time,” Fenna says. “Most people want the route and stop listening when they have it. I like that you want to know who opens the door.” She stretches out her legs. “Also, this bench is exceptionally good.”'),
 'kaede':('A pause with no lesson','Kaede sets her practice cord aside. “We do not have to improve at anything for a little while.”','Kaede points to the amber light inside her cup. “I used to hold coloured glass against a lamp to compare it with the finished piece. That colour was always harder to keep once the glass cooled.” She turns the cup. “I still want to make a panel that looks like this.”'),
 'elowen':('A small extravagant comfort','Elowen has saved a fragrant leaf for the shared kettle. “It changes nothing essential. I wanted it anyway.”','“Lemon balm by the seat. Thyme where I can brush it with my sleeve. Something with flowers I can cut without losing every bloom.” Elowen inhales the steam. “And one shelf too high for a cat. I have learned to budget for the cat.”'),
 'nyssara':('Off duty, visibly','Nyssara unfastens her outer cloak. “There. Evidence that I am not secretly keeping watch while claiming to rest.”','Nyssara watches the rain run past the shelter. “At home you could tell whose workshop was open by the lamps under the doors. One neighbour left his burning after he went to bed so nobody would call him lazy.” She smiles. “The snoring compromised the deception.”'),
 'sylva':('An excellent place to linger','Sylva finds the warmest patch of the bench and leaves room beside her. “No discovery. No emergency. Just a rather good place.”','“A traveller described a magnificent flowering tree to me for ten minutes. I asked what she liked best. She said it was the only shade on the road.” Sylva stretches her hands along the warm bench. “I liked her better for that answer. Where would you stop if you were choosing?”')
}
PAIRS=[
 ('mira','neris','Mira proposes a precise label. Neris asks whether anyone will understand it while cold and tired. Mira crosses out half the words.'),
 ('tamsin','zahra','Tamsin starts counting the work still ahead. Zahra counts the empty cups instead. “We can solve this problem first.”'),
 ('iona','sabine','Iona offers a grand introduction for Sabine’s improvised travel outfit. Sabine supplies an even grander entrance, taking exactly one step.'),
 ('aurelia','kaede','Aurelia asks whether sitting still counts as practice. Kaede replies, “Only if you stop trying to win.”'),
 
 ('koharu','elowen','Koharu explains how she would improve the kettle. Elowen pours the tea before the explanation can become another job.'),
 ('fenna','sylva','Fenna points out the quickest way onward. Sylva points out the best place to sit. They agree that both belong on the map.')
]
